# OrderLine: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Orderline:
    order_id: str = None  # FK
    line: float = None  # Line #
    sku: str = None  # FK
    qty: float = None  # Qty
    unit_price: float = None  # USD

REQUIRED = ["order_id", "line", "sku", "qty"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'order_id': 'ORD-8812001', 'line': 1, 'sku': 'SKU-WIDGET-BLU', 'qty': 3, 'unit_price': 29.99}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

